SELECT DATE_FORMAT(a.ENDDATE, '%Y-%m-%d') AS `日期`, b.SEC_SNAME AS `股票名称`, b.SEC_CODE AS `股票代码`, ROUND(a.CHNG_PCT_YEAR_SOFAR, 2) AS `今年以来涨跌幅(%)` FROM ANA_STK_EXPR_IDX a JOIN GET_A_SEC_CODE b ON a.INNER_CODE = b.INNER_CODE WHERE b.SEC_SNAME LIKE '%海康威视%' AND a.ENDDATE = '2026-09-02 00:00:00' AND a.CHNG_PCT_YEAR_SOFAR IS NOT NULL LIMIT 1;
